mapper.select:
SELECT 
  FROM ESS_LEAVE_APPLY_PARAM ESS
 WHERE ESS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND ESS.TYPE = 'pa'

   AND ESS.APPLY_TYPE = #{applyType, jdbcType=VARCHAR}

 ORDER BY ESS.APPLY_TYPE, ESS.APPLY_PARAM_NO

SELECT COUNT(1)
  FROM ESS_LEAVE_APPLY_PARAM ESS
 WHERE ESS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND ESS.APPLY_TYPE = #{applyType, jdbcType=VARCHAR}
   AND ESS.EMP_TYPE = #{empType, jdbcType=VARCHAR}
   AND ESS.DUTY_NO = #{dutyNo, jdbcType=VARCHAR}

   AND ESS.APPLY_PARAM_NO <> #{excludeApplyParamNo, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM ESS_LEAVE_APPLY_PARAM
 WHERE APPLY_PARAM_NO = #{applyParamNo, jdbcType=NUMERIC}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND TYPE = 'pa'
